{
  "goal": "Analyze sales CSV and generate summary report at /home/aiuser/Desktop/sales_summary.txt",
  "assumptions": [
    "sales_data.csv exists",
    "python3 available"
  ],
  "success_criteria": [
    {
      "tool": "file.query",
      "args": {
        "path": "/home/aiuser/Desktop/sales_summary.txt"
      }
    }
  ],
  "steps": [
    {
      "id": "step-1",
      "purpose": "Verify sales CSV exists and inspect structure",
      "tool": "data.csv_read",
      "args": {
        "path": "/home/aiuser/Documents/sales_data.csv",
        "max_rows": 5
      },
      "depends_on": [],
      "risk": "read_only",
      "captures": {
        "header_info": "stdout:first_line"
      },
      "verify": []
    },
    {
      "id": "step-2",
      "purpose": "Compute total and averages via python script",
      "tool": "command.argv",
      "args": {
        "argv": [
          "python3",
          "-c",
          "import csv; data=list(csv.reader(open('/home/aiuser/Documents/sales_data.csv'))); print(f'Rows: {len(data)-1}')"
        ]
      },
      "depends_on": [
        "step-1"
      ],
      "risk": "read_only",
      "captures": {
        "calc_summary": "stdout:strip"
      },
      "verify": []
    },
    {
      "id": "step-3",
      "purpose": "Write summary report to /home/aiuser/Desktop/sales_summary.txt",
