{
  "goal": "Archive downloaded files from /home/aiuser/Downloads to /home/aiuser/Documents/Archive and update log",
  "assumptions": [
    "Directories accessible and writable"
  ],
  "success_criteria": [
    {
      "tool": "dir.query",
      "args": {
        "path": "/home/aiuser/Documents/Archive"
      }
    },
    {
      "tool": "file.query",
      "args": {
        "path": "/home/aiuser/Documents/archive_log.txt"
      }
    }
  ],
  "steps": [
    {
      "id": "step-1",
      "purpose": "Ensure archive directory /home/aiuser/Documents/Archive exists",
      "tool": "dir.create",
      "args": {
        "path": "/home/aiuser/Documents/Archive"
      },
      "depends_on": [],
      "risk": "change",
      "verify": [
        {
          "tool": "dir.query",
          "args": {
            "path": "/home/aiuser/Documents/Archive"
          }
        }
      ]
    },
    {
      "id": "step-2",
      "purpose": "List files in /home/aiuser/Downloads to be archived",
      "tool": "file.list",
      "args": {
        "path": "/home/aiuser/Downloads",
        "pattern": "*.log"
      },
      "depends_on": [
        "step-1"
      ],
      "risk": "read_only",
      "captures": {
        "file_list": "stdout:strip"
      },
      "verify": []
    },
    {
      "id": "step-3",
      "purpose": "Move logs to /home/aiuser/Documents/Archive",
      "tool": "command.argv",
      "args": {
        "argv": [
          "sh",
          "-c",
          "mv /home/aiuser/Downloads/*.log /home/aiuser/Documents/Archive/ 2>/dev/null || true"
        ]
      },
      "depends_on": [
        "step-2"
      ],
      "risk": "change",
      "verify": [
        {
          "tool": "dir.query",
          "args": {
            "path": "/home/aiuser/Documents/Archive"
          }
        }
      ]
    },
    {
      "id": "step-4",
      "purpose": "Record archiving action in /home/aiuser/Documents/archive_log.txt",
      "tool": "file.append",
      "args": {
        "path": "/home/aiuser/Documents/archive_log.txt",
        "content": "Archived files: ${scratchpad.file_list}\n"
      },
      "depends_on": [
        "step-3"
      ],
      "risk": "change",
      "verify": [
        {
          "tool": "file.query",
          "args": {
            "path": "/home/aiuser/Documents/archive_log.txt"
          }
        }
      ]
    }
  ]
}

